import {sceneName,labels} from './data.js';
import {icon,esc,el,button,toast,openSheet,closeSheet,isSheetOpen} from './ui.js';
import {createSession,transition,selectRange} from './session.js';
import {directionText} from './reader.js';
import {getClip,AudioPlayer} from './audio.js';
export function mountRehearsal(main,ctx){const {data,small,progress,save}=ctx;let cleanup=()=>{},disposed=false;const player=new AudioPlayer();
 const holder=el('<div style="display:contents"></div>');main.append(holder);let active=null;
 function chooser(){cleanup();player.stop();holder.innerHTML=`<div class="page-scroll"><div class="page" style="max-width:860px"><div class="page-intro"><div class="eyebrow">TURN WORDS INTO YOUR VOICE</div><h1>稽古をはじめよう。</h1><p class="subtle">相手の言葉を受けて、自分のセリフを思い出す。</p></div><div class="role-box"><div class="role-monogram">${esc(small.role[0])}</div><div style="min-width:0;flex:1"><label for="rehearsal-role">自分の役</label><select id="rehearsal-role" class="role-select">${ctx.roles().map(r=>`<option ${r===small.role?'selected':''}>${esc(r)}</option>`).join('')}</select></div></div><div class="section-heading" style="margin-top:26px"><h2>練習する範囲</h2></div><div class="range-form"><label class="full">幕・場面<select id="range-scene"><option value="all">全幕を通して</option>${data.scenes.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></label><label>開始発話（選択範囲内）<input type="number" id="range-from" min="1" value="${small.range.from||1}" inputmode="numeric"></label><label>終了発話（選択範囲内）<input type="number" id="range-to" min="1" value="${small.range.to||data.lines.length}" inputmode="numeric"></label></div><p id="range-note" class="subtle"></p><div id="range-error"></div><div class="mode-options"><button class="mode-option" data-mode="cloze">${icon('book')}<span><strong>台本穴埋め</strong><small>自分のセリフを隠して、会話の流れで覚える。</small></span>${icon('chevron')}</button><button class="mode-option" data-mode="audio">${icon('audio')}<span><strong>音声稽古</strong><small>相手のセリフを聴き、自分の番で声にする。</small></span>${icon('chevron')}</button></div>${Object.entries(small.sessions||{}).filter(([,s])=>s.role===small.role).map(([mode,s])=>`<div class="setting-row"><div><strong>${mode==='cloze'?'台本穴埋め':'音声稽古'}の続き</strong><p>${esc(sceneName(s.range.scene))} · ${s.index+1}発話目</p></div><button class="secondary" data-resume="${mode}">再開 ${icon('arrow')}</button></div>`).join('')}<p class="keyboard-note">稽古中は Space / Enter で正解表示・次へ。← で前の発話。</p></div></div>`;
 const scene=holder.querySelector('#range-scene'),from=holder.querySelector('#range-from'),to=holder.querySelector('#range-to');scene.value=small.range.scene||'all';
 function count(){return scene.value==='all'?data.lines.length:data.lines.filter(l=>l.scene===scene.value).length;}
 function update(reset=false){const n=count();from.max=to.max=n;if(reset){from.value=1;to.value=n;}const selected=data.lines.filter(l=>scene.value==='all'||l.scene===scene.value).slice(Math.max(0,+from.value-1),+to.value);holder.querySelector('#range-note').textContent=`${n}発話中 ${selected.length}発話を練習 · 自分のセリフ ${selected.filter(l=>l.speaker===small.role).length}件`;small.range={scene:scene.value,from:+from.value,to:+to.value};save();}
 if(!small.range.to)to.value=count();scene.onchange=()=>update(true);from.oninput=()=>update();to.oninput=()=>update();update();holder.querySelector('#rehearsal-role').onchange=e=>{small.role=e.target.value;save();chooser();};
 holder.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{try{const range={scene:scene.value,from:+from.value,to:+to.value};const lines=selectRange(data,range);start(b.dataset.mode,range,lines,0);}catch(err){holder.querySelector('#range-error').innerHTML=`<p class="notice error" role="alert" style="margin-top:14px">${esc(err.message)}</p>`;}});
 holder.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>{const s=small.sessions[b.dataset.resume];try{const lines=selectRange(data,s.range);start(b.dataset.resume,s.range,lines,Math.max(0,lines.findIndex(l=>l.id===s.lineId)));}catch(err){toast('前回の範囲を復元できません。範囲を選び直してください。');}});
 }
 function start(mode,range,lines,index){cleanup();player.stop();let state=createSession(lines,small.role,mode,index),epoch=0,playingError='',revealed=new Set(),lineNodes=[],scroller,body,controls,stage;
 active={mode,range};const persist=()=>{small.sessions||={};if(state.phase==='complete')delete small.sessions[mode];else small.sessions[mode]={role:small.role,range,index:state.index,lineId:lines[state.index].id};save();};
 holder.innerHTML=`<div class="reader-top"><div class="reader-heading"><button class="icon-button" data-action="exit" aria-label="稽古の設定に戻る">${icon('back')}</button><div><h1>${mode==='cloze'?'台本穴埋め':'音声稽古'}</h1><span class="reader-count">${esc(small.role)} · ${esc(sceneName(range.scene))}</span></div></div><span class="reader-count" id="session-counter"></span></div><div class="session-progress" role="progressbar" aria-label="稽古の進行" aria-valuemin="0" aria-valuemax="${lines.length}" aria-valuenow="0"><span></span></div>`;
 if(mode==='cloze'){scroller=el('<div class="page-scroll rehearsal" tabindex="0" aria-label="穴埋め台本"></div>');body=el('<div class="script-body"></div>');body.style.setProperty('--font',small.font+'px');body.style.setProperty('--reader-leading',small.leading);scroller.append(body);holder.append(scroller);
  let scene='';for(const line of lines){if(scene!==line.scene){scene=line.scene;body.append(el(`<div class="scene-divider"><h2>${esc(sceneName(scene))}</h2></div>`));}const own=line.speaker===small.role,n=el(`<article class="speech ${own?'mine':''}" data-id="${esc(line.id)}"><div class="speech-head"><span class="speaker">${esc(line.speaker)}</span><span class="line-number">${line.ordinal.toString().padStart(3,'0')}</span></div>${line.direction?`<p class="direction">${esc(directionText(line.direction))}</p>`:''}<div class="line-content"></div></article>`);body.append(n);lineNodes.push(n);if(!own)n.querySelector('.line-content').innerHTML=`<p lang="en" class="speech-text">${esc(line.text)}</p>`;}
 }else{stage=el('<div class="audio-stage"></div>');holder.append(stage);}
 controls=el('<div class="session-controls"></div>');holder.append(controls);holder.querySelector('[data-action=exit]').onclick=()=>{epoch++;persist();chooser();};
 const setPhase=event=>{state=transition(state,event,lines);persist();};
 function act(){if(state.phase==='complete')return;if(state.phase==='hidden'){revealed.add(lines[state.index].id);setPhase('reveal');paint();}else{epoch++;player.stop();setPhase('next');paint();if(mode==='audio')loadAudio();}}
 function previous(){if(state.index<=0)return;epoch++;player.stop();setPhase('previous');revealed.delete(lines[state.index].id);paint();if(mode==='audio')loadAudio();}
 function rate(level,review){const line=lines[state.index];ctx.setProgress(line.id,{...progress[line.id],...(level!==null?{level}:{}),...(review!==undefined?{review}:{}),updatedAt:Date.now()});paint();}
 function paint(){const complete=state.phase==='complete';holder.querySelector('#session-counter').textContent=`${Math.min(state.index+1,lines.length)} / ${lines.length}`;const bar=holder.querySelector('.session-progress');bar.setAttribute('aria-valuenow',complete?lines.length:state.index);bar.firstElementChild.style.width=`${(complete?1:state.index/lines.length)*100}%`;
  if(complete){player.stop();const content=el(`<div class="page-scroll"><div class="complete">${icon('check')}<h2>この範囲の稽古が終わりました。</h2><p>${lines.length} 発話 · 自分のセリフ ${lines.filter(l=>l.speaker===small.role).length}件<br>おつかれさまでした。次の一回で、もっと自然に。</p><div class="button-row">${button('もう一度','again','primary','refresh')}${button('範囲を選び直す','choose','secondary')}</div></div></div>`);if(scroller)scroller.replaceWith(content);if(stage)stage.replaceWith(content);controls.replaceChildren();content.querySelector('[data-action=again]').onclick=()=>start(mode,range,lines,0);content.querySelector('[data-action=choose]').onclick=chooser;return;}
  const line=lines[state.index],own=line.speaker===small.role,show=state.phase==='revealed';
  if(mode==='cloze'){
   lineNodes.forEach((n,i)=>{n.classList.toggle('current',i===state.index);n.classList.toggle('previous',i<state.index);n.classList.toggle('future',i>state.index);if(lines[i].speaker===small.role){const text=n.querySelector('.line-content');if(revealed.has(lines[i].id)){text.innerHTML=`<p lang="en" class="speech-text">${esc(lines[i].text)}</p>`;}else{text.innerHTML=`<button class="reveal-mask" ${i===state.index?'':'disabled'}>${icon('play')}${i===state.index?'声に出して思い出す · タップで正解':'自分のセリフ'}</button>`;if(i===state.index)text.querySelector('button').onclick=act;}}});
   const n=lineNodes[state.index];n.onclick=e=>{if(!e.target.closest('button')&&state.index===lineNodes.indexOf(n))act();};n.scrollIntoView({block:'center',behavior:'instant'});
  }else{
   const phaseText={hidden:'YOUR TURN',revealed:'ANSWER',ready:'準備中',playing:'相手のセリフを再生中',paused:'一時停止',cue:'相手のセリフが終了',missing:'音声未登録 · 手動で進行',error:'再生できません'}[state.phase];
   stage.innerHTML=`<div class="audio-inner"><div class="eyebrow">${esc(sceneName(line.scene))} · 発話 ${line.ordinal}</div><div class="audio-symbol">${icon(own?'play':state.phase==='playing'?'audio':'pause')}</div><div class="eyebrow" role="status">${phaseText}</div><h2 class="audio-speaker">${esc(line.speaker)}</h2>${line.direction?`<p class="audio-note">${esc(directionText(line.direction))}</p>`:''}${own?show?`<p class="audio-answer" lang="en">${esc(line.text)}</p>`:'<p class="audio-cue">自分のセリフを声に出してみましょう。<br>思い出せたら、タップで確認。</p>':`<p class="audio-cue">${state.phase==='missing'?'この発話の音声はまだ追加されていません。<br>相手のセリフを確認して、手動で進められます。':state.phase==='error'?esc(playingError):'相手の言葉を聴いて、次のセリフにつなげよう。'}</p><details class="audio-note"><summary>相手のセリフを確認</summary><p class="audio-answer" lang="en">${esc(line.text)}</p></details>`}${!own&&['playing','paused','cue','error'].includes(state.phase)?`<div class="button-row">${button(state.phase==='playing'?'一時停止':state.phase==='paused'?'再生を続ける':'もう一度再生','transport','secondary',state.phase==='playing'?'pause':'play')}</div>`:''}<p class="audio-note">${own?(show?'もう一度タップして次へ':'答えは確認するまで表示されません'):'音声認識による採点は行いません'}</p></div>`;
   stage.onclick=e=>{if(!e.target.closest('button,summary,details')&&own)act();};stage.querySelector('[data-action=transport]')?.addEventListener('click',async()=>{if(state.phase==='playing'){player.pause();setPhase('pause');paint();}else if(state.phase==='paused'){try{await player.resume();setPhase('playing');paint();}catch{playingError='再生を続けられません。もう一度再生してください。';state={...state,phase:'error'};paint();}}else loadAudio();});
  }
  controls.innerHTML=`<button class="secondary" data-action="previous" ${state.index===0?'disabled':''}>${icon('back')}<span>前へ</span></button><div class="subtle">${own?(show?'答えを確認して次へ':'自分のセリフを思い出す'):'相手のセリフ'}</div><div class="button-row">${own&&show?`<button class="icon-button" data-action="mark-review" aria-label="要復習にする" aria-pressed="${!!progress[line.id]?.review}">${icon('bookmark')}</button><button class="secondary" data-action="mastered">覚えた</button>`:''}<button class="primary" data-action="advance">${own&&!show?'正解を表示':state.phase==='playing'?'再生を止めて次へ':'次の発話へ'}${icon('arrow')}</button></div>`;
  controls.querySelector('[data-action=previous]').onclick=previous;controls.querySelector('[data-action=advance]').onclick=act;controls.querySelector('[data-action=mark-review]')?.addEventListener('click',()=>rate(null,!progress[line.id]?.review));controls.querySelector('[data-action=mastered]')?.addEventListener('click',()=>rate(2));
 }
 async function loadAudio(){if(mode!=='audio'||state.phase==='complete'||lines[state.index]?.speaker===small.role)return;const token=++epoch;player.stop();state={...state,phase:'ready'};playingError='';paint();try{const clip=await getClip(data.id,lines[state.index].id);if(disposed||token!==epoch)return;if(!clip){setPhase('missing');paint();return;}setPhase('playing');paint();await player.play(clip,{rate:small.rate,onended:()=>{if(disposed||token!==epoch)return;setPhase('ended');if(document.hidden){paint();return;}setPhase('next');paint();loadAudio();},onerror:err=>{if(disposed||token!==epoch)return;playingError=err.message;setPhase('error');paint();}});}catch(err){if(disposed||token!==epoch)return;playingError=err.name==='NotAllowedError'?'再生にはタップが必要です。「もう一度再生」を押してください。':`音声を再生できません。${err.message}`;state={...state,phase:'error'};paint();}}
 const key=e=>{if(isSheetOpen()||e.target.closest('button,input,select,textarea,summary,a'))return;if(e.code==='Space'||e.key==='Enter'){e.preventDefault();act();}else if(e.key==='ArrowLeft'){e.preventDefault();previous();}};
 const hide=()=>{if(document.hidden&&state.phase==='playing'){player.pause();setPhase('pause');paint();}};
 window.addEventListener('keydown',key);document.addEventListener('visibilitychange',hide);cleanup=()=>{epoch++;persist();player.stop();window.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',hide);};persist();paint();if(mode==='audio')loadAudio();
 }
 chooser();return ()=>{disposed=true;cleanup();player.stop();};
}
